import java.util.*; class Cart07{private final double[]prices;private int count;private final String id;Cart07(String i,int n){id=i;prices=new double[Math.max(0,n)];}boolean addItem(double p){if(p<0||count==prices.length)return false;prices[count++]=p;return true;}double getTotal(){double t=0;for(int i=0;i<count;i++)t+=prices[i];return t;}int getItemCount(){return count;}String getId(){return id;}} public class Week07Problem05{public static void main(String[]z){Scanner s=new Scanner(System.in);Cart07 c=new Cart07(s.next(),s.nextInt());int n=s.nextInt();for(int i=0;i<n;i++)c.addItem(s.nextDouble());System.out.println("Cart: "+c.getId());System.out.println("Items: "+c.getItemCount());System.out.printf("Total: %.2f%n",c.getTotal());}}